<?php
require_once __DIR__.'/includes/bootstrap.php';require_auth();if(!can_manage()){http_response_code(403);exit('Accès refusé.');}$page_title='Nouveau dépôt';
$clients=db()->query("SELECT id,nom,prenom,telephone FROM clients ORDER BY nom")->fetchAll();$services=db()->query("SELECT * FROM services WHERE active=1 ORDER BY nom")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$client=(int)$_POST['client_id'];$type=$_POST['type_depot']==='express'?'express':'normal';$date=$_POST['date_prevue'];$ids=$_POST['service_id']??[];$qty=$_POST['quantite']??[];$descs=$_POST['description']??[];if(!$ids||!$client){flash('Choisissez un client et au moins un service.','error');redirect('order_new.php');}
$pdo=db();$pdo->beginTransaction();try{$code='PR-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(2)));$pdo->prepare("INSERT INTO orders(code,client_id,user_id,type_depot,date_prevue,notes) VALUES(?,?,?,?,?,?)")->execute([$code,$client,$_SESSION['user']['id'],$type,$date,$_POST['notes']??'']);$oid=(int)$pdo->lastInsertId();$total=0;$coutTotal=0;$ins=$pdo->prepare("INSERT INTO order_items(order_id,service_id,description,quantite,prix_unitaire,cout_unitaire,subtotal) VALUES(?,?,?,?,?,?,?)");foreach($ids as $i=>$sid){$q=max(1,(int)($qty[$i]??1));$st=$pdo->prepare("SELECT nom,prix,cout_estime FROM services WHERE id=? AND active=1");$st->execute([(int)$sid]);$sv=$st->fetch();if(!$sv)continue;$prix=(float)$sv['prix'];$cout=(float)$sv['cout_estime'];$sub=$q*$prix;$total+=$sub;$coutTotal+=$q*$cout;$ins->execute([$oid,(int)$sid,trim($descs[$i]??$sv['nom']),$q,$prix,$cout,$sub]);}$surcharge=($type==='express')?round($total*EXPRESS_SURCHARGE_PERCENT/100):0;$totalFinal=$total+$surcharge;$pdo->prepare("UPDATE orders SET total=?,surcharge_express=? WHERE id=?")->execute([$totalFinal,$surcharge,$oid]);$pdo->commit();flash('Dépôt créé : '.$code);redirect('order_view.php?id='.$oid);}catch(Throwable $e){$pdo->rollBack();flash('Erreur lors de la création du dépôt.','error');redirect('order_new.php');}}
require 'includes/header.php';?>
<div class="form-card"><form method="post" id="orderForm"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="form-grid"><div class="field"><label>Client *</label><select name="client_id" required><option value="">Sélectionner un client</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>"><?=e($c['prenom'].' '.$c['nom'].' · '.$c['telephone'])?></option><?php endforeach;?></select><?php if(!$clients):?><small>Ajoutez d'abord un client dans le menu Clients.</small><?php endif;?></div><div class="field"><label>Type de dépôt</label><select name="type_depot"><option value="normal">Normal</option><option value="express">Express (+<?=EXPRESS_SURCHARGE_PERCENT?>%)</option></select></div><div class="field"><label>Date prévue de retrait</label><input type="date" name="date_prevue" min="<?=date('Y-m-d')?>" value="<?=date('Y-m-d',strtotime('+2 days'))?>" required></div><div class="field"><label>Note interne</label><input name="notes" placeholder="Informations complémentaires"></div></div><hr style="border:0;border-top:1px solid #e7ebf3;margin:22px 0"><h2>Articles et prestations</h2><p class="muted">Tarifs indicatifs en FCFA. Le dépôt express applique une majoration de <?=EXPRESS_SURCHARGE_PERCENT?>% pour mieux couvrir l'urgence et préserver votre marge.</p><?php for($i=0;$i<3;$i++):?><div class="form-grid" style="margin-bottom:13px"><div class="field"><label>Service</label><select name="service_id[]"><option value="">— Aucun —</option><?php foreach($services as $s):?><option value="<?=$s['id']?>"><?=e($s['nom'])?> · <?=money($s['prix'])?></option><?php endforeach;?></select></div><div class="field"><label>Quantité</label><input type="number" name="quantite[]" min="1" value="1"></div><div class="field full"><label>Description des vêtements (ex. chemises, pantalons)</label><input name="description[]" placeholder="Description"></div></div><?php endfor;?><button class="btn" type="submit" <?=!$clients||!$services?'disabled':''?>>Créer le dépôt</button> <a class="btn light" href="orders.php">Annuler</a></form></div>
